-- Aidi data import (Oct 2026, v2): client services → Finvry clients; group model and financials → Aidi OS. Idempotent.
BEGIN;
CREATE OR REPLACE FUNCTION pg_temp.norm(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT regexp_replace(lower(coalesce(t,'')), '[^a-z0-9]', '', 'g') $$;
CREATE OR REPLACE FUNCTION pg_temp.ent(org uuid, nm text, k text, jur text, st text) RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE r uuid; BEGIN
  SELECT id INTO r FROM core.entities WHERE organization_id = org AND pg_temp.norm(name) = pg_temp.norm(nm) LIMIT 1;
  IF r IS NULL THEN INSERT INTO core.entities (organization_id, name, kind, jurisdiction, status) VALUES (org, nm, k, jur, st) RETURNING id INTO r; END IF;
  RETURN r; END $$;
CREATE OR REPLACE FUNCTION pg_temp.slug(nm text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE b text := trim(both '-' from regexp_replace(lower(nm), '[^a-z0-9]+', '-', 'g')); s text; i int := 1; BEGIN
  b := left(b, 36); s := b;
  WHILE EXISTS (SELECT 1 FROM core.organizations WHERE slug = s) LOOP i := i + 1; s := b || '-' || i; END LOOP;
  RETURN s; END $$;
CREATE OR REPLACE FUNCTION pg_temp.stmt(org uuid, ent uuid, pt text, pe date, cur text, ln jsonb, nt text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE r uuid; BEGIN
  SELECT id INTO r FROM financials.statements WHERE entity_id = ent AND period_type = pt AND period_end = pe;
  IF r IS NULL THEN INSERT INTO financials.statements (organization_id, entity_id, period_type, period_end, currency, lines, kpis, notes, source) VALUES (org, ent, pt, pe, cur, ln, '{}'::jsonb, nt, 'manual');
  ELSE UPDATE financials.statements SET currency = cur, lines = ln, notes = nt WHERE id = r AND (source = 'manual' AND coalesce(notes, '') LIKE 'Imported%'); END IF; END $$;
DO $imp$
DECLARE aidi uuid; op uuid; e uuid; ws uuid; cl uuid; co uuid; br uuid; ln uuid; acc uuid; f_angel uuid; lp uuid; n int := 0;
  e_av uuid; e_aw uuid; e_ah uuid; e_at uuid; e_tl uuid; e_tlt uuid; e_ti uuid; e_tw uuid; e_siu uuid; e_siung uuid; e_af1 uuid; e_angel uuid;
BEGIN
  SELECT id INTO aidi FROM core.organizations WHERE plan_code = 'internal' ORDER BY created_at LIMIT 1;
  SELECT id INTO op FROM core.organizations WHERE settings->>'services_operator' = 'true' ORDER BY created_at LIMIT 1; IF op IS NULL THEN op := aidi; END IF;
  IF aidi IS NULL THEN RAISE EXCEPTION 'Aidi workspace not found'; END IF;
  e_av := pg_temp.ent(aidi, 'Aidi Ventures LLC', 'holding', 'US-DE', 'active');
  UPDATE core.entities SET tax_id = coalesce(tax_id, '37-2007053'), registration_number = coalesce(registration_number, NULL), formation_date = coalesce(formation_date, '2021-06-07'::date), address = coalesce(address, '2055 Limestone Rd, Ste 200C, Wilmington, DE 19808') WHERE id = e_av;
  e_aw := pg_temp.ent(aidi, 'Aidi Wealth LLC', 'operating', 'US-CA', 'active');
  UPDATE core.entities SET tax_id = coalesce(tax_id, '39-2434680'), registration_number = coalesce(registration_number, NULL), formation_date = coalesce(formation_date, '2025-05-30'::date), address = coalesce(address, '6203 San Ignacio Ave, Ste 110, San Jose, CA 95119') WHERE id = e_aw;
  e_ah := pg_temp.ent(aidi, 'Aidi Haven LLC', 'operating', 'US-CA', 'active');
  UPDATE core.entities SET tax_id = coalesce(tax_id, '33-3663563'), registration_number = coalesce(registration_number, NULL), formation_date = coalesce(formation_date, '2025-02-25'::date), address = coalesce(address, '2880 Zanker Rd, Ste 203, San Jose, CA 95134') WHERE id = e_ah;
  e_at := pg_temp.ent(aidi, 'Aidi Technology Limited', 'operating', 'NG', 'active');
  UPDATE core.entities SET tax_id = coalesce(tax_id, NULL), registration_number = coalesce(registration_number, '1779621'), formation_date = coalesce(formation_date, '2021-04-05'::date), address = coalesce(address, '150 Ikorodu Road, Onipanu, Lagos State, Nigeria') WHERE id = e_at;
  e := pg_temp.ent(aidi, 'Aidi Finance Limited', 'operating', 'NG', 'forming');
  e_tl := pg_temp.ent(aidi, 'Telroi LLC', 'holding', 'US-CA', 'active');
  UPDATE core.entities SET tax_id = coalesce(tax_id, '39-3128556'), registration_number = coalesce(registration_number, NULL), formation_date = coalesce(formation_date, NULL::date), address = coalesce(address, NULL) WHERE id = e_tl;
  e_tlt := pg_temp.ent(aidi, 'Telroi Limited', 'operating', 'NG', 'active');
  UPDATE core.entities SET tax_id = coalesce(tax_id, NULL), registration_number = coalesce(registration_number, '9030304'), formation_date = coalesce(formation_date, NULL::date), address = coalesce(address, NULL) WHERE id = e_tlt;
  e_ti := pg_temp.ent(aidi, 'Termii Inc', 'other', 'US-DE', 'active');
  e_tw := pg_temp.ent(aidi, 'Termii Webtech Limited', 'other', 'NG', 'active');
  e_siu := pg_temp.ent(aidi, 'Siu Telecoms Inc', 'other', 'US', 'active');
  e_siung := pg_temp.ent(aidi, 'Siu Telecommunications Network Ltd', 'other', 'NG', 'active');
  e_af1 := pg_temp.ent(aidi, 'Aidi Ventures Fund I', 'fund', 'US-DE', 'forming');
  e := pg_temp.ent(aidi, 'Aidi Ventures Fund I GP, LLC', 'gp', 'US-DE', 'forming');
  e := pg_temp.ent(aidi, 'Aidi Ventures Fund I Management, LLC', 'management_company', 'US-DE', 'forming');
  e := pg_temp.ent(aidi, 'TAG Trust', 'trust', 'US', 'forming');
  e := pg_temp.ent(aidi, 'TAG Family Trust', 'trust', 'US', 'forming');
  e_angel := pg_temp.ent(aidi, 'Aidi Angel Fund', 'fund', 'US-DE', 'active');
  UPDATE core.entities SET parent_id = e_av WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Aidi Wealth LLC') AND parent_id IS NULL AND id <> e_av;
  UPDATE core.entities SET parent_id = e_av WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Aidi Haven LLC') AND parent_id IS NULL AND id <> e_av;
  UPDATE core.entities SET parent_id = e_av WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Aidi Technology Limited') AND parent_id IS NULL AND id <> e_av;
  UPDATE core.entities SET parent_id = e_av WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Aidi Finance Limited') AND parent_id IS NULL AND id <> e_av;
  UPDATE core.entities SET parent_id = e_av WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Telroi LLC') AND parent_id IS NULL AND id <> e_av;
  UPDATE core.entities SET parent_id = e_av WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Aidi Angel Fund') AND parent_id IS NULL AND id <> e_av;
