  UPDATE core.entities SET parent_id = e_ti WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Termii Webtech Limited') AND parent_id IS NULL AND id <> e_ti;
  UPDATE core.entities SET parent_id = e_siu WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Siu Telecommunications Network Ltd') AND parent_id IS NULL AND id <> e_siu;
