  PERFORM pg_temp.stmt(aidi, e_av, 'year', '2021-12-31', 'USD', '{"revenue": 1169.19, "cogs": 0.0, "opex_marketing": 0.0, "opex_payroll": 0.0, "opex_ga": 8240.95, "tax": 0.0, "opex_total": 8240.95, "ebitda": -7071.76, "depreciation": 0.0, "net_income": -7086.76, "cash": 4488.18, "total_assets": 34488.18, "debt": 37317.6, "total_liabilities": 37574.94, "equity": -3086.76, "other_liabilities": 257.34, "other_assets": 30000.0}'::jsonb, 'Imported from the Aidi Group financial model (TAG financials), FY2021');
