DO $wl$
DECLARE aidi uuid; e_av uuid; e_aw uuid; e_ah uuid; e_tl uuid; e_angel uuid; e_fam uuid; f_angel uuid; lp uuid;
BEGIN
  SELECT id INTO aidi FROM core.organizations WHERE plan_code = 'internal' ORDER BY created_at LIMIT 1;
  SELECT id INTO e_av FROM core.entities WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Aidi Ventures LLC') LIMIT 1;
  SELECT id INTO e_aw FROM core.entities WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Aidi Wealth LLC') LIMIT 1;
  SELECT id INTO e_ah FROM core.entities WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Aidi Haven LLC') LIMIT 1;
  SELECT id INTO e_tl FROM core.entities WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Telroi LLC') LIMIT 1;
  SELECT id INTO e_angel FROM core.entities WHERE organization_id = aidi AND pg_temp.norm(name) = pg_temp.norm('Aidi Angel Fund') LIMIT 1;
  e_fam := pg_temp.ent(aidi, 'Gbolade family (private)', 'household', 'US', 'active');
  INSERT INTO wealth.holdings (organization_id, entity_id, client_name, section, category, name, platform, currency, cost, current_value, realized, ownership_pct, status, as_of, notes, meta, in_nav, in_aum, import_key) SELECT aidi, e_tl, NULL, 'family', 'private_stake', 'Termii Inc stake', NULL, 'USD', NULL, 7555707.88, NULL, 30.2, 'active', '2026-08-31', 'Held personally by E. Gbolade; contribution to Telroi LLC not yet done or approved. 56.9% of voting stock, 30.2% fully diluted (Sep 2026 cap table). Conservative: last priced round ($25m).', '{"mgmt_value": 13600274.18, "level": "L3"}'::jsonb, true, true, '|Termii Inc stake' WHERE NOT EXISTS (SELECT 1 FROM wealth.holdings WHERE organization_id = aidi AND import_key = '|Termii Inc stake');
