  INSERT INTO wealth.holdings (organization_id, entity_id, client_name, section, category, name, platform, currency, cost, current_value, realized, ownership_pct, status, as_of, notes, meta, in_nav, in_aum, import_key) SELECT aidi, e_av, NULL, 'family', 'venture', 'Aidi Angel Fund portfolio: Aidi (firm) share, unrealized', NULL, 'USD', NULL, 83971.33, NULL, NULL, 'active', '2026-08-31', 'Firm share of the portfolio; conservative applies a 30% haircut to management marks. Company-level positions are under Venture positions.', '{"mgmt_value": 119959.0403, "level": "L3"}'::jsonb, true, true, '|Aidi Angel Fund portfolio: Aidi (firm) share, unrealized' WHERE NOT EXISTS (SELECT 1 FROM wealth.holdings WHERE organization_id = aidi AND import_key = '|Aidi Angel Fund portfolio: Aidi (firm) share, unrealized');
  INSERT INTO wealth.holdings (organization_id, entity_id, client_name, section, category, name, platform, currency, cost, current_value, realized, ownership_pct, status, as_of, notes, meta, in_nav, in_aum, import_key) SELECT aidi, e_ah, NULL, 'family', 'real_estate', 'Aidi Haven property interests (book value)', NULL, 'USD', NULL, 4281.89, NULL, NULL, 'active', '2026-08-31', 'Both apartments are leased (master lease), so held at FY25 book equity. Estimated market values are shown under Real estate (not in NAV).', '{"level": "L3"}'::jsonb, true, true, '|Aidi Haven property interests (book value)' WHERE NOT EXISTS (SELECT 1 FROM wealth.holdings WHERE organization_id = aidi AND import_key = '|Aidi Haven property interests (book value)');
